package com.spms.repository;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.domain.*;import java.util.*;import java.time.*;import com.spms.entity.*; public interface EmployeeRepository extends JpaRepository<Employee,UUID>{Optional<Employee> findByUserAccountUsername(String username); Optional<Employee> findByEmployeeCode(String code); Page<Employee> findByFullNameContainingIgnoreCaseOrEmployeeCodeContainingIgnoreCase(String name,String code,Pageable pageable);}